"use client";

import "./field.css";
import { Field as BaseField } from "@base-ui/react/field";
import type React from "react";
import { cn } from "@/lib/cn";

import { FieldContext, useFieldContext } from "./field.context";
import { fieldVariants, type FieldVariants } from "./field.variants";

export type FieldProps = FieldVariants &
  React.ComponentProps<typeof BaseField.Root> & {
    label?: React.ReactNode;
    description?: React.ReactNode;
    error?: React.ReactNode;
  };

export const FieldRoot = ({
  children,
  className,
  size,
  label,
  description,
  error,
  ...props
}: FieldProps) => {
  const slots = fieldVariants({ size });

  return (
    <FieldContext.Provider value={{ slots }}>
      <BaseField.Root className={cn(slots.root(), className)} {...props}>
        {label && <FieldLabel>{label}</FieldLabel>}
        {children}
        {description && <FieldDescription>{description}</FieldDescription>}
        {error && <FieldError>{error}</FieldError>}
      </BaseField.Root>
    </FieldContext.Provider>
  );
};

export type FieldLabelProps = React.ComponentProps<typeof BaseField.Label>;

export const FieldLabel = ({ className, ...props }: FieldLabelProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Label className={cn(slots.label(), className)} {...props} />;
};

export type FieldControlProps = React.ComponentProps<typeof BaseField.Control>;

export const FieldControl = ({ className, render, ...props }: FieldControlProps) => {
  const { slots } = useFieldContext();
  return (
    <BaseField.Control
      className={cn(slots.control(), className)}
      render={render}
      {...props}
    />
  );
};

export type FieldErrorProps = React.ComponentProps<typeof BaseField.Error>;

export const FieldError = ({ className, ...props }: FieldErrorProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Error className={cn(slots.error(), className)} {...props} />;
};

export type FieldDescriptionProps = React.ComponentProps<typeof BaseField.Description>;

export const FieldDescription = ({ className, ...props }: FieldDescriptionProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Description className={cn(slots.description(), className)} {...props} />;
};

export type FieldItemProps = React.ComponentProps<typeof BaseField.Item>;

export const FieldItem = ({ className, ...props }: FieldItemProps) => {
  const { slots } = useFieldContext();
  return <BaseField.Item className={cn(slots.item(), className)} {...props} />;
};

export type FieldGroupProps = React.ComponentProps<"div">;

export const FieldGroup = ({ className, ...props }: FieldGroupProps) => {
  const { slots } = useFieldContext();
  return <div role="group" className={cn(slots.group(), className)} {...props} />;
};

export type FieldPrefixProps = React.ComponentProps<"div">;

export const FieldPrefix = ({ className, ...props }: FieldPrefixProps) => {
  const { slots } = useFieldContext();
  return <div className={cn(slots.prefix(), className)} {...props} />;
};

export type FieldSuffixProps = React.ComponentProps<"div">;

export const FieldSuffix = ({ className, ...props }: FieldSuffixProps) => {
  const { slots } = useFieldContext();
  return <div className={cn(slots.suffix(), className)} {...props} />;
};

export type FieldValidityProps = React.ComponentProps<typeof BaseField.Validity>;

export const FieldValidity = (props: FieldValidityProps) => {
  return <BaseField.Validity {...props} />;
};

export const Field = FieldRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const fieldVariants = tv({
  slots: {
    root: "field",
    label: "field__label",
    control: "field__control",
    error: "field__error",
    description: "field__description",
    item: "field__item",
    group: "field__group",
    prefix: "field__prefix",
    suffix: "field__suffix",
  },
  variants: {
    size: {
      sm: {
        label: "field__label--sm",
        control: "field__control--sm",
        group: "field__group--sm",
        prefix: "field__prefix--sm",
        suffix: "field__suffix--sm",
      },
      md: {
        label: "field__label--md",
        control: "field__control--md",
        group: "field__group--md",
        prefix: "field__prefix--md",
        suffix: "field__suffix--md",
      },
      lg: {
        label: "field__label--lg",
        control: "field__control--lg",
        group: "field__group--lg",
        prefix: "field__prefix--lg",
        suffix: "field__suffix--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type FieldVariants = VariantProps<typeof fieldVariants>;

"use client";

import { createContext, useContext } from "react";

import { fieldVariants } from "./field.variants";

export type FieldContext = {
  slots: ReturnType<typeof fieldVariants>;
};

export const FieldContext = createContext<FieldContext | null>(null);

export const useFieldContext = () => {
  const context = useContext(FieldContext);
  return context ?? { slots: fieldVariants() };
};

.field {
  @apply text-foreground flex w-full flex-col items-start gap-1.5;
}

.field__label {
  @apply text-foreground data-invalid:text-destructive text-sm font-medium select-none data-disabled:opacity-50;
}

.field__label--sm {
  @apply text-xs;
}

.field__label--md {
  @apply text-sm;
}

.field__label--lg {
  @apply text-base;
}

.field__control {
  @apply border-input bg-background placeholder:text-muted-foreground focus-visible:outline-ring data-invalid:border-destructive data-invalid:focus-visible:outline-destructive h-9 w-full rounded-md border px-3 py-1 text-sm shadow-xs transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.field__control--sm {
  @apply h-8 px-2.5 text-xs;
}

.field__control--md {
  @apply h-9 px-3 text-sm;
}

.field__control--lg {
  @apply h-10 px-3.5 text-base;
}

.field__group {
  @apply border-input bg-background focus-within:outline-ring data-invalid:border-destructive data-invalid:focus-within:outline-destructive in-[[data-invalid]]:border-destructive in-[[data-invalid]]:focus-within:outline-destructive has-[[data-invalid]]:border-destructive has-[[data-invalid]]:focus-within:outline-destructive relative flex w-full items-center rounded-md border shadow-xs transition-colors focus-within:outline-2 disabled:cursor-not-allowed disabled:opacity-50 in-[[data-disabled]]:cursor-not-allowed in-[[data-disabled]]:opacity-50 has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-50 data-disabled:cursor-not-allowed data-disabled:opacity-50;
}

.field__group--sm {
  @apply h-8 text-xs;
}

.field__group--md {
  @apply h-9 text-sm;
}

.field__group--lg {
  @apply h-10 text-base;
}

.field__prefix {
  @apply text-muted-foreground flex shrink-0 items-center justify-center pr-1.5 pl-3 text-sm select-none;
}

.field__prefix--sm {
  @apply pr-1 pl-2.5 text-xs;
}

.field__prefix--md {
  @apply pr-1.5 pl-3 text-sm;
}

.field__prefix--lg {
  @apply pr-2 pl-3.5 text-base;
}

.field__suffix {
  @apply text-muted-foreground flex shrink-0 items-center justify-center pr-3 pl-1.5 text-sm select-none;
}

.field__suffix--sm {
  @apply pr-2.5 pl-1 text-xs;
}

.field__suffix--md {
  @apply pr-3 pl-1.5 text-sm;
}

.field__suffix--lg {
  @apply pr-3.5 pl-2 text-base;
}

.field__group input,
.field__group select,
.field__group textarea,
.field__group .field__control,
.field__group .input,
.field__group .native-select,
.field__group .textarea {
  @apply placeholder:text-muted-foreground h-full w-full min-w-0 flex-1 border-none bg-transparent px-3 py-1 text-sm shadow-none outline-none focus:ring-0 focus:outline-none focus-visible:ring-0 focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50;
}

.field__prefix ~ input,
.field__prefix ~ select,
.field__prefix ~ textarea,
.field__prefix ~ .field__control,
.field__prefix ~ .input,
.field__prefix ~ .native-select,
.field__prefix ~ .textarea {
  @apply pl-1.5;
}

input:has(~ .field__suffix),
select:has(~ .field__suffix),
textarea:has(~ .field__suffix),
.field__control:has(~ .field__suffix),
.input:has(~ .field__suffix),
.native-select:has(~ .field__suffix),
.textarea:has(~ .field__suffix) {
  @apply pr-1.5;
}

.field__error {
  @apply text-destructive text-xs font-medium transition-all duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0;
}

.field__description {
  @apply text-muted-foreground text-xs;
}

.field__item {
  @apply flex items-center gap-2;
}
